using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpRestServer;

/// <summary>
/// Each public method decorated with [McpServerTool] becomes a discoverable MCP tool.
/// The MCP SDK resolves constructor and method parameters via the DI container.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _http;

    // Constructor-injected HttpClient — resolved from DI via IHttpClientFactory.
    // The SDK creates an instance of this class per tool invocation,
    // injecting registered services into the constructor.
    public WeatherTools(HttpClient httpClient)
    {
        _http = httpClient;
    }

    [McpServerTool("get_current_weather")]
    [Description("Gets the current weather for a given city using the Open-Meteo API.")]
    public async Task<string> GetCurrentWeatherAsync(
        [Description("City latitude (e.g. 47.6 for Seattle)")] double latitude,
        [Description("City longitude (e.g. -122.3 for Seattle)")] double longitude)
    {
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}&current=temperature_2m,wind_speed_10m";

        var response = await _http.GetFromJsonAsync<WeatherResponse>(url);
        if (response?.Current is null)
            return "Unable to fetch weather data.";

        var c = response.Current;
        return $"Temperature: {c.Temperature}°C, Wind: {c.WindSpeed} km/h";
    }

    [McpServerTool("get_forecast")]
    [Description("Gets a 7-day daily max/min temperature forecast.")]
    public async Task<string> GetForecastAsync(
        [Description("City latitude")] double latitude,
        [Description("City longitude")] double longitude)
    {
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}&daily=temperature_2m_max,temperature_2m_min&timezone=auto";

        var response = await _http.GetFromJsonAsync<ForecastResponse>(url);
        if (response?.Daily is null)
            return "Unable to fetch forecast data.";

        var lines = new List<string>();
        for (var i = 0; i < response.Daily.Time.Count; i++)
        {
            lines.Add($"{response.Daily.Time[i]}: {response.Daily.MaxTemp[i]}°C / {response.Daily.MinTemp[i]}°C");
        }

        return string.Join("\n", lines);
    }

    // --- DTOs for Open-Meteo JSON responses ---

    private sealed record WeatherResponse(
        [property: JsonPropertyName("current")] CurrentWeather? Current);

    private sealed record CurrentWeather(
        [property: JsonPropertyName("temperature_2m")] double Temperature,
        [property: JsonPropertyName("wind_speed_10m")] double WindSpeed);

    private sealed record ForecastResponse(
        [property: JsonPropertyName("daily")] DailyForecast? Daily);

    private sealed record DailyForecast(
        [property: JsonPropertyName("time")] List<string> Time,
        [property: JsonPropertyName("temperature_2m_max")] List<double> MaxTemp,
        [property: JsonPropertyName("temperature_2m_min")] List<double> MinTemp);
}

